#!/usr/bin/env node
/**
 * Unified security-header inspection (Issue #449).
 *
 *   node scripts/check-security-headers.mjs [--headers=path] [--json]
 *
 * Why this exists
 * ---------------
 * Cloudflare documents that "Custom headers defined in the `_headers`
 * file are not applied to responses generated by your Worker code, even
 * if the request URL matches a rule." So the shipped site has TWO
 * surfaces carrying these headers:
 *
 *   1. `src/http/security-headers.ts` — everything the Worker generates
 *      (SSR documents, redirects, server functions, `/api/v1/*`).
 *   2. `public/_headers` — everything Cloudflare Static Assets serves
 *      (`/assets/*`, `/share/**`, the Tool artefacts, favicon).
 *
 * They cannot be produced by one function, so nothing but a check keeps
 * them from drifting apart. The canonical VALUES live in
 * `src/http/security-headers.json`; this script asserts that surface 2
 * reproduces them, and that the per-Tool permission grants in the Tool
 * manifest (`delivery.iframe.allow`, Issue #449) are mirrored for BOTH
 * surfaces — the shell route through the Worker, the artefact through
 * `_headers`.
 *
 * What it checks
 * --------------
 *   1. `/*` carries the host baseline: nosniff, the host
 *      `Referrer-Policy`, and the deny-list `Permissions-Policy`.
 *   2. The Tool artefact rules (`/tools/:slug/app*`) carry nosniff,
 *      the Tool `Referrer-Policy`, and the deny-list policy — a Tool
 *      must not reach a capture device just by being framed.
 *   3. Every manifest `iframe.allow` is a list of FEATURE NAMES that
 *      the baseline actually denies (an unknown feature makes the grant
 *      a no-op, which is worse than an error because it looks applied).
 *   4. Every manifest `iframe.allow` has a matching per-slug `_headers`
 *      rule granting exactly those features, scoped to the canonical
 *      production origin.
 *   5. No `_headers` rule grants a feature no manifest entry declares,
 *      and the wildcard Tool rule never grants a capture device.
 *
 * Rule semantics
 * --------------
 * `_headers` rules are applied in file order and every matching rule
 * contributes: a later rule overrides an earlier one for the same
 * header. `resolveHeadersForPath()` implements exactly that, so the
 * per-Tool grant is resolved through the same model the platform uses.
 * If that assumption is ever wrong the failure mode is fail-closed —
 * the Tool loses the microphone; it does not silently gain it.
 *
 * Exit code 0 when the two surfaces agree, 1 on any violation (each
 * printed as `<file>  <message>`).
 */
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { PRODUCTION_BETTER_AUTH_URL } from './_cloudflare-contract.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');

/** Header names, lower-cased — `_headers` is case-insensitive. */
const NOSNIFF = 'x-content-type-options';
const REFERRER_POLICY = 'referrer-policy';
const PERMISSIONS_POLICY = 'permissions-policy';

/** The canonical policy the Worker emits (see `src/http/security-headers.ts`). */
export function loadPolicy(policyPath = resolve(root, 'src/http/security-headers.json')) {
	return JSON.parse(readFileSync(policyPath, 'utf8'));
}

/**
 * Render the `Permissions-Policy` value for a set of granted features.
 * Mirrors `permissionsPolicyValue()` in the Worker module — same order,
 * same allowlist — so the comparison is byte-for-byte.
 */
export function permissionsPolicyValue(policy, origin, granted = []) {
	const grantedSet = new Set(granted.map((feature) => feature.trim().toLowerCase()));
	const allowlist = policy.granted_origin_token.replace('{origin}', origin);
	return policy.denied_permissions
		.map((feature) =>
			grantedSet.has(feature.toLowerCase()) ? `${feature}=${allowlist}` : `${feature}=()`,
		)
		.join(', ');
}

/**
 * Parse a Cloudflare / Netlify `_headers` file into ordered rules.
 * A rule is a path line followed by indented `Name: value` lines;
 * `#` comments and blank lines are ignored.
 */
export function parseHeadersFile(source) {
	const rules = [];
	let current = null;
	for (const rawLine of source.split('\n')) {
		const line = rawLine.replace(/\s+$/, '');
		const trimmed = line.trim();
		if (trimmed === '' || trimmed.startsWith('#')) continue;
		if (!/^\s/.test(line)) {
			current = { path: trimmed, headers: {} };
			rules.push(current);
			continue;
		}
		if (!current) continue;
		const separator = trimmed.indexOf(':');
		if (separator === -1) continue;
		const name = trimmed.slice(0, separator).trim().toLowerCase();
		const value = trimmed.slice(separator + 1).trim();
		current.headers[name] = value;
	}
	return rules;
}

/** Compile a `_headers` path pattern into a RegExp (`:slug` = one segment). */
export function patternToRegExp(pattern) {
	const escaped = pattern
		.replace(/[.+?^${}()|[\]\\]/g, '\\$&')
		.replace(/:([a-zA-Z0-9_]+)/g, '[^/]+')
		.replace(/\*/g, '.*');
	return new RegExp(`^${escaped}$`);
}

/** Effective headers for a path: every matching rule, later wins. */
export function resolveHeadersForPath(rules, pathname) {
	const effective = {};
	for (const rule of rules) {
		if (!patternToRegExp(rule.path).test(pathname)) continue;
		Object.assign(effective, rule.headers);
	}
	return effective;
}

/** Features a `Permissions-Policy` value grants (i.e. does not deny). */
export function grantedFeatures(value) {
	if (!value) return [];
	return value
		.split(',')
		.map((entry) => entry.trim())
		.filter((entry) => entry.length > 0)
		.filter((entry) => !entry.endsWith('=()'))
		.map((entry) => entry.split('=')[0].trim().toLowerCase());
}

/**
 * A concrete request path that exercises a `_headers` rule. `:slug` is
 * filled with a Tool that declares NO grant, so a wildcard rule that
 * quietly widens the policy is measured on the Tool least entitled to it.
 */
export function probePathFor(pattern, manifest) {
	const ungranted =
		manifest.tools.find((tool) => declaredFeatures(tool.delivery?.iframe?.allow).length === 0)
			?.slug ?? 'prototype';
	if (pattern.endsWith('/*')) return `${pattern.slice(0, -1)}${ungranted}/probe-file.txt`;
	return pattern.replace(':slug', ungranted);
}

/** Canonical artefact namespace for a Tool (see the registry). */
export function artifactPathFor(tool) {
	return tool.delivery?.kind === 'same_origin_static'
		? tool.delivery.artifact_path
		: `/tools/${tool.slug}/app`;
}

/** Exact-prefix-or-/ match. */
export function pathnameMatches(prefix, pathname) {
	return pathname === prefix || pathname.startsWith(`${prefix}/`);
}

/** Manifest feature names, whitespace-split. */
export function declaredFeatures(allow) {
	if (!allow) return [];
	return String(allow)
		.split(/\s+/)
		.map((token) => token.trim())
		.filter((token) => token.length > 0);
}

/**
 * Run every check. Returns `{ violations, inspected }`; `violations` is
 * an array of human-readable strings.
 */
export function inspect(options = {}) {
	const policy = loadPolicy(options.policyPath);
	const headersPath = options.headersPath ?? resolve(root, 'public/_headers');
	const manifestPath = options.manifestPath ?? resolve(root, 'src/tools/manifest.json');
	const rules = parseHeadersFile(readFileSync(headersPath, 'utf8'));
	const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
	const productionOrigin = new URL(PRODUCTION_BETTER_AUTH_URL).origin;

	const baseline = permissionsPolicyValue(policy, productionOrigin);
	const violations = [];

	const expectHeader = (pathname, name, expected) => {
		const actual = resolveHeadersForPath(rules, pathname)[name];
		if (actual !== expected) {
			violations.push(
				`public/_headers  ${pathname}  ${name}: expected "${expected}", got "${actual ?? '(absent)'}"`,
			);
		}
	};

	// 1. Host baseline for every static byte.
	const sample = '/share/procon2026/index.html';
	expectHeader(sample, NOSNIFF, policy.x_content_type_options);
	expectHeader(sample, REFERRER_POLICY, policy.referrer_policy.host);
	expectHeader(sample, PERMISSIONS_POLICY, baseline);

	// 2. Tool artefact rules: same deny list, Tool referrer policy. The
	//    sample uses a slug with no declared grant so the wildcard rule
	//    is measured on its own.
	const grantedTools = [];
	for (const tool of manifest.tools) {
		const declared = declaredFeatures(tool.delivery?.iframe?.allow);
		if (declared.length === 0) continue;
		grantedTools.push({
			slug: tool.slug,
			declared,
			referrer: tool.delivery.iframe.referrer_policy,
		});
		for (const token of declared) {
			if (/[=()]/.test(token)) {
				violations.push(
					`src/tools/manifest.json  ${tool.slug}  delivery.iframe.allow: "${token}" is not a bare feature name (the host owns the origin allowlist)`,
				);
			}
			if (!policy.denied_permissions.includes(token)) {
				violations.push(
					`src/tools/manifest.json  ${tool.slug}  delivery.iframe.allow: "${token}" is not in the denied baseline, so the grant would be a no-op`,
				);
			}
		}
	}
	const ungranted = manifest.tools.find(
		(tool) => declaredFeatures(tool.delivery?.iframe?.allow).length === 0,
	);
	if (ungranted) {
		const artifact = ungranted.delivery?.artifact_path ?? '/tools/prototype/app';
		expectHeader(`${artifact}/index.html`, NOSNIFF, policy.x_content_type_options);
		expectHeader(`${artifact}/index.html`, REFERRER_POLICY, policy.referrer_policy.tool_app);
		expectHeader(`${artifact}/index.html`, PERMISSIONS_POLICY, baseline);
	}

	// 4. A per-slug rule for every declared grant.
	for (const { slug, declared, referrer } of grantedTools) {
		const sample = `/tools/${slug}/app/index.html`;
		const effective = resolveHeadersForPath(rules, sample);
		expectHeader(sample, NOSNIFF, policy.x_content_type_options);
		expectHeader(sample, REFERRER_POLICY, referrer ?? policy.referrer_policy.tool_app);
		expectHeader(
			sample,
			PERMISSIONS_POLICY,
			permissionsPolicyValue(policy, productionOrigin, declared),
		);
		const granted = grantedFeatures(effective[PERMISSIONS_POLICY]);
		for (const feature of declared) {
			if (!granted.includes(feature)) {
				violations.push(
					`public/_headers  ${sample}  permissions-policy: declared grant "${feature}" is not applied to the Tool artefact`,
				);
			}
		}
	}

	// 5. A granted feature may appear ONLY inside the artefact namespace
	//    of the Tool that declares it. This is the machine form of the
	//    separation the Issue asks for: the microphone is a per-Tool
	//    decision, never a host-wide or wildcard-Tool relaxation.
	for (const rule of rules) {
		const probe = probePathFor(rule.path, manifest);
		const granted = grantedFeatures(resolveHeadersForPath(rules, probe)[PERMISSIONS_POLICY]);
		for (const feature of granted) {
			const owner = manifest.tools.find((tool) =>
				declaredFeatures(tool.delivery?.iframe?.allow).includes(feature),
			);
			if (!owner) {
				violations.push(
					`public/_headers  ${rule.path}  permissions-policy: grants "${feature}" but no Tool manifest entry declares it`,
				);
				continue;
			}
			const namespace = artifactPathFor(owner);
			if (!pathnameMatches(namespace, probe)) {
				violations.push(
					`public/_headers  ${rule.path}  permissions-policy: grants "${feature}" outside the declaring Tool's namespace ${namespace} (probe ${probe})`,
				);
			}
		}
	}

	return { violations, rules, policy, productionOrigin, grantedTools, baseline };
}

/**
 * Render the effective header matrix for a path, for docs / the
 * verification report. Reuses the same rule model as the check.
 */
export function headerMatrix(policy, rules) {
	return [
		{ surface: 'Worker', path: '/ (any host document)', value: baselineFor(policy, null) },
		{
			surface: 'Worker',
			path: '/tools/<slug> with delivery.iframe.allow',
			value: baselineFor(policy, 'microphone'),
		},
		{
			surface: 'Static Assets',
			path: '/share/**, /assets/*, favicon',
			value: baselineFor(policy, null),
		},
		{
			surface: 'Static Assets',
			path: '/tools/<slug>/app/** (no grant)',
			value: baselineFor(policy, null),
		},
	];
}

function baselineFor(policy, granted) {
	const origin = new URL(PRODUCTION_BETTER_AUTH_URL).origin;
	const headers = {
		[NOSNIFF]: policy.x_content_type_options,
		[REFERRER_POLICY]: granted ? policy.referrer_policy.tool_app : policy.referrer_policy.host,
		[PERMISSIONS_POLICY]: permissionsPolicyValue(policy, origin, granted ? [granted] : []),
	};
	return headers;
}

export function main(argv = process.argv.slice(2)) {
	const asJson = argv.includes('--json');
	const headersArg = argv.find((arg) => arg.startsWith('--headers='));
	const result = inspect(headersArg ? { headersPath: resolve(headersArg.split('=')[1]) } : {});

	if (asJson) {
		console.log(
			JSON.stringify({ violations: result.violations, grantedTools: result.grantedTools }),
		);
	} else {
		const [origin] = [result.productionOrigin];
		console.log(`[check-security-headers] canonical origin: ${origin}`);
		console.log(
			`[check-security-headers] denied baseline: ${permissionsPolicyValue(result.policy, origin)}`,
		);
		console.log(
			`[check-security-headers] _headers rules: ${result.rules.map((rule) => rule.path).join(', ')}`,
		);
		console.log(
			`[check-security-headers] Tool grants: ${
				result.grantedTools.length === 0
					? 'none'
					: result.grantedTools
							.map((tool) => `${tool.slug} -> ${tool.declared.join(',')}`)
							.join('; ')
			}`,
		);
		for (const violation of result.violations) console.error(`  ${violation}`);
	}
	if (result.violations.length > 0) {
		console.error(
			`[check-security-headers] ${result.violations.length} violation(s): public/_headers does not match src/http/security-headers.json`,
		);
		process.exitCode = 1;
		return;
	}
	console.log('[check-security-headers] ok. Worker policy and public/_headers agree.');
}

const invokedDirectly =
	process.argv[1] !== undefined &&
	resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url));
if (invokedDirectly) main();
